package br.com.conectatea.conexao.infrastructure; import br.com.conectatea.conexao.domain.ConexaoProfissional; import java.util.List; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface ConexaoRepository extends JpaRepository<ConexaoProfissional,Long>{@Query("select c from ConexaoProfissional c where c.solicitanteId=:id or c.destinatarioId=:id")List<ConexaoProfissional> findMine(@Param("id")Long id);}
